/* @jsx h */
import type { Register } from 'claude-code'
import { classify } from './games/signals.ts'
import { isBetter } from './games/best.ts'

// Four games above the prompt — /racer, /breakout, /dino, /shooter — one open at a time. A game's state
// lives entirely in its board (./boards/*.tsx); this module registers the commands, bumps the pause banner
// when Claude finishes a turn, turns a classified tool call into a "pulse" the open board applies once,
// and keeps each game's best score.

type Game = 'racer' | 'breakout' | 'dino' | 'shooter'
const GAMES: Game[] = ['racer', 'breakout', 'dino', 'shooter']
const isGame = (v: unknown): v is Game => GAMES.includes(v as Game)
const HINT: Record<Game, string> = {
  racer: 'click the board, then ↑ ↓ or w/s switch lanes',
  breakout: 'click the board, then ← → or a/d move, space launches',
  dino: 'click the board, then space/↑ jump, ↓ duck',
  shooter: 'click the board, then ↑ ↓ move, space fires',
}
const DESCRIPTION: Record<Game, string> = {
  racer: 'A scrolling dodge race above the prompt — speed climbs as you go, and Claude\'s real work clears lanes, drops hazards, or hands you a shield (claude-games)',
  breakout: 'Breakout above the prompt — paddle, ball and bricks, harder every level, and Claude\'s real work breaks bricks, armors them, or hands you lives (claude-games)',
  dino: 'The dinosaur runner above the prompt — jump cacti, duck birds, faster every second, and Claude\'s real work clears the way, drops cacti, or shields you (claude-games)',
  shooter: 'A side-scrolling shooter above the prompt — waves fly in from the right, and Claude\'s real work powers your gun, sends extra enemies, or drops a bomb (claude-games)',
}

let active: Game | undefined
let turnsDone = 0
let pulseSeq = 0
// null, not undefined, until the first real tool call: Client props must be plain data, and the engine
// refuses a props object holding an undefined value
let lastPulse: { type: 'edit' | 'test-pass' | 'test-fail' | 'commit'; seq: number } | null = null
const best: Record<Game, number> = { racer: 0, breakout: 0, dino: 0, shooter: 0 }

// /<game> opens it (closing whichever was open), /<game> stop closes it
function command(game: Game, args: string) {
  if (args.trim().toLowerCase() === 'stop') {
    if (active === game) active = undefined
    return `${game} closed`
  }
  active = game
  return `${game} · ${HINT[game]} · best ${best[game]} · /${game} stop closes`
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    const r = await next(e)
    for (const game of GAMES) {
      const saved = await $.store.get(`best:${game}`).catch(err => { $.ui.log(`claude-games: store read failed: ${err}`); return undefined })
      const n = Number(saved)
      if (n) best[game] = n
      await $.command.register({ name: game, description: DESCRIPTION[game], argumentHint: '[stop]', immediate: true })
        .catch(err => $.ui.log(`claude-games: /${game} not registered: ${err}`))
    }
    return r
  })

  on('command.run', { command: 'racer' }, async ($, e) => {
    const text = command('racer', e.args)
    $.ui.invalidate('ui.render')
    return { text }
  })

  on('command.run', { command: 'breakout' }, async ($, e) => {
    const text = command('breakout', e.args)
    $.ui.invalidate('ui.render')
    return { text }
  })

  on('command.run', { command: 'dino' }, async ($, e) => {
    const text = command('dino', e.args)
    $.ui.invalidate('ui.render')
    return { text }
  })

  on('command.run', { command: 'shooter' }, async ($, e) => {
    const text = command('shooter', e.args)
    $.ui.invalidate('ui.render')
    return { text }
  })

  on('turn.complete', async ($, e, next) => {
    const r = await next(e)
    if (active) {
      turnsDone++
      $.ui.invalidate('ui.render')
    }
    return r
  })

  // every finished tool call is a possible pulse: classified, then handed to the open board as a bumped
  // sequence number so it applies it exactly once
  on('tool.call', async ($, e, next) => {
    const r = await next(e)
    const cmd = (e as { command?: unknown }).command
    const event = classify(e.tool, typeof cmd === 'string' ? cmd : undefined, 'deny' in r ? undefined : !r.isError)
    if (!event) return r
    pulseSeq++
    lastPulse = { type: event, seq: pulseSeq }
    if (active) $.ui.invalidate('ui.render')
    return r
  })

  // a finished run or game, posted by its board
  on('ui.message', async ($, e, next) => {
    const data = e.data as { game?: unknown; score?: unknown } | null
    const game = data?.game
    const score = data?.score
    if (!isGame(game) || typeof score !== 'number') return next(e)
    if (isBetter(score, best[game])) {
      best[game] = score
      await $.store.set(`best:${game}`, score).catch(err => $.ui.log(`claude-games: store write failed: ${err}`))
      $.ui.toast(`${game}: new best ${score}`)
    }
    return { props: { pulse: lastPulse, best: best[game], done: turnsDone } }
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    // the boards need a terminal; the desktop and mobile surfaces draw their own band
    if (!active || e.props.hasSurvey || e.surface !== 'terminal') return next(e)
    const { Box, Button, Client } = await $.ui.resolve(e)
    const cols = e.viewport?.columns ?? 80
    const tall = Math.max(8, e.props.maxRows - 2)
    const props = { pulse: lastPulse, best: best[active], done: turnsDone }
    const close = () => {
      active = undefined
      $.ui.invalidate('ui.render')
    }
    // module paths must be string literals, since the engine reads them off this source. The racer
    // draws exactly 8 rows (5 of road, its border, its status line) so it asks for exactly that; the
    // pixel games size themselves to whatever height they're given.
    const board =
      active === 'racer' ? <Client key="board:racer" module="./boards/racer.tsx" width={cols} height={8} props={props} />
      : active === 'breakout' ? <Client key="board:breakout" module="./boards/breakout.tsx" width={cols} height={tall} props={props} />
      : active === 'dino' ? <Client key="board:dino" module="./boards/dino.tsx" width={cols} height={tall} props={props} />
      : <Client key="board:shooter" module="./boards/shooter.tsx" width={cols} height={tall} props={props} />
    return (
      <Box flexDirection="column">
        <Box flexDirection="row" columnGap={1}>
          <Button key="arcade:close" label="close" onPress={close} />
        </Box>
        {board}
        {await next(e)}
      </Box>
    )
  })
}

