// Classifies a finished tool call as one of Claude's real, observable build events. Pure; the hooks
// module supplies the finished call. Lifted from cc-arcade's pet-feeding classifier — the boss fight
// is driven by the same four real signals, nothing fabricated.

export type BuildEvent = 'test-pass' | 'test-fail' | 'commit' | 'edit'

// test runners across common stacks; a failing run is a tool call that ended in error
const TEST_COMMAND = /\b(bun|npm|pnpm|yarn)\s+(run\s+)?test\b|\bnpx\s+(jest|vitest|mocha)\b|\b(pytest|jest|vitest|rspec|phpunit|mocha)\b|\bgo\s+test\b|\bcargo\s+test\b|\bmake\s+test\b|\b(mvn|gradle|gradlew|sbt)\b.*\btest\b/

// what a finished tool call means for the fight; `ok` is undefined when the call was denied
export function classify(tool: string, command: string | undefined, ok: boolean | undefined): BuildEvent | undefined {
  if (ok === undefined) return undefined
  if (tool === 'Bash' && command) {
    if (TEST_COMMAND.test(command)) return ok ? 'test-pass' : 'test-fail'
    if (ok && /\bgit\s+commit\b/.test(command) && !/--dry-run\b/.test(command)) return 'commit'
    return undefined
  }
  if (ok && (tool === 'Edit' || tool === 'Write' || tool === 'NotebookEdit')) return 'edit'
  return undefined
}

