/* @jsx h */
import type { ClientSurface } from 'claude-code'
import { base, claudeDone, grid, statusLine, type Base, type Paint } from './common.tsx'
import { newRacer, pulse, steer, tick, type Pulse, type Racer } from '../games/racer.ts'

// Terminal Racer's board. Your car sits fixed near the left edge, facing right; oncoming cars enter at
// the right edge and scroll toward you, in one of three lanes stacked top to bottom. A run's state lives
// entirely here (like the original cc-arcade pong/snake boards did) — only the best distance is posted
// up and persisted. register.tsx pushes Claude's real events down as a "pulse" (a bumped sequence
// number, same idiom claudeDone uses for props.done); this board applies each one once.

type Props = { pulse: { type: Pulse; seq: number } | null; best?: number; done?: number } | undefined
type State = Base & { g: Racer; seenPulseSeq: number }

// Cars are pixel art drawn with half blocks: each character is one pixel wide and two pixels tall
// (▀ paints the top pixel in the text color and the bottom one in the background), so a car one row
// tall is two pixels tall and CAR_W track cells (two characters each) wide. b = body, w = window,
// k = wheel, space = road. Yours faces right; oncoming ones face left and each rolls its own shape and
// color from its `look` at spawn.
const CAR = [
  ' bw ',
  'kbbk',
]
const ONCOMING = [
  [' wb ', 'kbbk'], // sedan
  ['wbbb', 'kbbk'], // van
  ['wb  ', 'kbbk'], // pickup
  ['bwwb', 'kbbk'], // bus
  [' w  ', 'kbbk'], // low sports car
]
const ONCOMING_COLORS = ['red', 'magenta', 'green', 'blue']
const lookOf = (look = 0) => ({
  sprite: ONCOMING[Math.floor(look * ONCOMING.length)],
  color: ONCOMING_COLORS[Math.floor(look * ONCOMING.length * ONCOMING_COLORS.length) % ONCOMING_COLORS.length],
})
const LANE_ROWS = CAR.length / 2
// every lane is LANE_ROWS tall with a dashed divider row between lanes: 3*1 + 2 = 5 rows. With the border
// and the status line that's 8, the least the band above the prompt ever gives a board, so no row can
// get squeezed out.
const rowsFor = (lanes: number) => lanes * LANE_ROWS + lanes - 1
const laneTop = (lane: number) => lane * (LANE_ROWS + 1)
const trackLenFor = (columns: number) => Math.max(20, Math.min(60, Math.floor((columns - 4) / 2)))

function paint(buf: Paint[][], sprite: string[], left: number, top: number, body: string) {
  const color = (p: string | undefined) => (p === 'b' ? body : p === 'w' ? 'white' : p === 'k' ? 'gray' : undefined)
  for (let r = 0; r < LANE_ROWS; r++) {
    for (let c = 0; c < sprite[0].length; c++) {
      const x = left + c
      const y = top + r
      if (y < 0 || y >= buf.length || x < 0 || x >= buf[0].length) continue
      const up = color(sprite[r * 2][c])
      const down = color(sprite[r * 2 + 1][c])
      if (!up && !down) continue
      buf[y][x] = !up ? ['▄', down] : !down ? ['▀', up] : up === down ? ['█', up] : ['▀', up, down]
    }
  }
}

export default function RacerBoard(props: Props, surface: ClientSurface<State>) {
  const { Box, Text } = surface.elements

  if (surface.state === undefined) {
    surface.setState({ ...base(props), playing: true, g: newRacer(trackLenFor(surface.columns)), seenPulseSeq: props?.pulse?.seq ?? 0 })
    surface.every(100, () => {
      const s = surface.state
      if (!s || !s.playing || s.banner || s.g.over) return
      const g = tick(s.g)
      if (g.over) surface.post({ game: 'racer', score: g.distance })
      surface.setState({ ...s, g })
    })
    // click the board to give it the keyboard: up/down switch lanes, space/p pauses, r restarts
    surface.onKey(({ key }) => {
      const s = surface.state
      if (!s) return
      const k = key === 'space' ? ' ' : key.toLowerCase()
      if (k === 'p' || k === ' ') {
        if (!s.g.over) surface.setState({ ...s, banner: false, playing: !s.playing })
        return
      }
      if (k === 'r') {
        surface.setState({ ...s, banner: false, playing: true, g: newRacer(trackLenFor(surface.columns)) })
        return
      }
      const dir = k === 'up' || k === 'w' ? -1 : k === 'down' || k === 's' ? 1 : 0
      if (!dir) return
      surface.setState({ ...s, banner: false, playing: true, g: steer(s.g, dir as -1 | 1) })
    })
  }
  claudeDone(props, surface)

  const s = surface.state
  if (!s) return <Text dimColor>racer · waiting for the plugin to load it</Text>

  // a real event landed since the last render: apply it once, same idiom claudeDone uses for props.done
  const seq = props?.pulse?.seq
  if (seq !== undefined && seq !== s.seenPulseSeq) {
    surface.setState({ ...s, seenPulseSeq: seq, g: pulse(s.g, props!.pulse!.type) })
  }

  const g = s.g
  const width = g.trackLen * 2
  const height = rowsFor(g.lanes)
  // the road: lane dividers as dashes that scroll left with the traffic, two characters per tick
  const buf: Paint[][] = Array.from({ length: height }, (_, y) =>
    Array.from({ length: width }, (_, x): Paint =>
      (y + 1) % (LANE_ROWS + 1) === 0 && (x + g.ticks * 2) % 8 < 4 ? ['─', 'gray'] : [' ']))
  for (const o of g.obstacles) {
    const { sprite, color } = lookOf(o.look)
    paint(buf, sprite, o.x * 2, laneTop(o.lane), color)
  }
  paint(buf, CAR, g.carX * 2, laneTop(g.car), g.shield > 0 ? 'yellow' : 'cyan')
  const rows = grid(Text, width, height, (x, y) => buf[y][x])

  const text = g.over ? `racer · crashed at ${g.distance} · r restarts`
    : !s.playing ? `racer · paused · ${g.distance} · space resumes`
    : `racer · ↑ ↓ or w/s switch lanes · speed ${g.speed.toFixed(1)}${g.shield > 0 ? ' · shielded' : ''} · ${g.distance}`

  return (
    <Box flexDirection="column">
      <Box flexDirection="column" borderStyle="round" borderColor={g.over ? 'red' : 'gray'} width={width + 2}>{rows}</Box>
      {statusLine(Text, !!s.banner, `${text} · best ${props?.best ?? 0}`)}
    </Box>
  )
}

