/* @jsx h */
import type { ClientSurface } from 'claude-code'
import { base, claudeDone, grid, halfBlock, statusLine, type Base } from './common.tsx'
import { BRICK_W, launch, movePaddle, newBreakout, pulse, tick, type Breakout, type Brick } from '../games/breakout.ts'
import type { BuildEvent } from '../games/signals.ts'

// Breakout's board. A game's state lives entirely here, like the racer's; only the final score is
// posted up. It sizes itself from the height the band actually gives it (border and status line take
// three rows), so no row is ever squeezed out, and draws in half-block pixels — each character is one
// pixel wide and two tall (▀ in the text color over the background color) — which doubles the vertical
// resolution the ball has to move in.

type Props = { pulse: { type: BuildEvent; seq: number } | null; best?: number; done?: number } | undefined
type State = Base & { g: Breakout; seenPulseSeq: number }

const ROW_COLORS = ['red', 'yellow', 'green', 'cyan', 'blue', 'magenta']
const sizeFor = (columns: number, rows: number) => ({
  w: Math.max(30, Math.min(64, columns - 4)),
  h: Math.max(8, (rows - 3) * 2),
})
// a row's color, alternating with its bright variant brick by brick so neighbors don't blur together;
// an armored brick is white until it's down to its last hit
const brickColor = (b: Brick) => {
  if (b.hp > 1) return b.hp > 2 ? 'whiteBright' : 'white'
  const color = ROW_COLORS[(b.y - 1) % ROW_COLORS.length]
  return (Math.floor(b.x / BRICK_W) + b.y) % 2 === 0 ? color : `${color}Bright`
}

const fresh = (surface: ClientSurface<State>) => {
  const { w, h } = sizeFor(surface.columns, surface.rows)
  return newBreakout(w, h)
}

export default function BreakoutBoard(props: Props, surface: ClientSurface<State>) {
  const { Box, Text } = surface.elements

  if (surface.state === undefined) {
    surface.setState({ ...base(props), playing: true, g: fresh(surface), seenPulseSeq: props?.pulse?.seq ?? 0 })
    surface.every(100, () => {
      const s = surface.state
      if (!s || !s.playing || s.banner || s.g.over) return
      const g = tick(s.g)
      if (g.over) surface.post({ game: 'breakout', score: g.score })
      surface.setState({ ...s, g })
    })
    // click the board to give it the keyboard: left/right move, space launches, p pauses, r restarts
    surface.onKey(({ key }) => {
      const s = surface.state
      if (!s) return
      const k = key === 'space' ? ' ' : key.toLowerCase()
      if (k === 'p') {
        if (!s.g.over) surface.setState({ ...s, banner: false, playing: !s.playing })
        return
      }
      if (k === 'r') {
        surface.setState({ ...s, banner: false, playing: true, g: fresh(surface) })
        return
      }
      if (k === ' ') {
        surface.setState({ ...s, banner: false, playing: true, g: launch(s.g) })
        return
      }
      const dir = k === 'left' || k === 'a' ? -1 : k === 'right' || k === 'd' ? 1 : 0
      if (!dir) return
      surface.setState({ ...s, banner: false, playing: true, g: movePaddle(s.g, dir as -1 | 1) })
    })
  }
  claudeDone(props, surface)

  const s = surface.state
  if (!s) return <Text dimColor>breakout · waiting for the plugin to load it</Text>

  // a real event landed since the last render: apply it once, same idiom claudeDone uses for props.done
  const seq = props?.pulse?.seq
  if (seq !== undefined && seq !== s.seenPulseSeq) {
    surface.setState({ ...s, seenPulseSeq: seq, g: pulse(s.g, props!.pulse!.type) })
  }

  const g = s.g
  const bricks = new Map<number, string>()
  for (const b of g.bricks) {
    const color = brickColor(b)
    for (let i = 0; i < BRICK_W; i++) bricks.set(b.y * g.w + b.x + i, color)
  }
  const ballX = Math.floor(g.ball.x)
  const ballY = Math.floor(g.ball.y)
  const pixel = (x: number, y: number): string | undefined =>
    x === ballX && y === ballY ? 'whiteBright'
      : y === g.h - 1 && x >= g.paddle && x < g.paddle + g.paddleW ? 'cyan'
      : bricks.get(y * g.w + x)
  const rows = grid(Text, g.w, g.h / 2, (x, r) => halfBlock(pixel(x, r * 2), pixel(x, r * 2 + 1)))

  const hud = `level ${g.level} · ${'♥'.repeat(g.lives)} · ${g.score}`
  const text = g.over ? `breakout · game over at ${g.score} · r restarts`
    : !s.playing ? `breakout · paused · ${hud} · p resumes`
    : !g.launched ? `breakout · ${hud} · ← → or a/d move · space launches`
    : `breakout · ${hud}`

  return (
    <Box flexDirection="column">
      <Box flexDirection="column" borderStyle="round" borderColor={g.over ? 'red' : 'gray'} width={g.w + 2}>{rows}</Box>
      {statusLine(Text, !!s.banner, `${text} · best ${props?.best ?? 0}`)}
    </Box>
  )
}

