/* @jsx h */
import type { ClientSurface } from 'claude-code'
import { base, canvas, claudeDone, statusLine, type Base } from './common.tsx'
import { box, DINO_X, DUCKED, duck, jump, newDino, pulse, tick, type Dino } from '../games/dino.ts'
import type { BuildEvent } from '../games/signals.ts'

// Dino Runner's board. A run's state lives entirely here; only the final score is posted up. It sizes
// itself from the height it's given and draws in half-block pixels on the shared canvas.

type Props = { pulse: { type: BuildEvent; seq: number } | null; best?: number; done?: number } | undefined
type State = Base & { g: Dino; seenPulseSeq: number }

const sizeFor = (columns: number, rows: number) => ({
  w: Math.max(30, Math.min(72, columns - 4)),
  h: Math.max(8, (rows - 3) * 2),
})

// sprites, top row first, facing right: d = dino, c = cactus, b = bird
const RUN = [
  ['   dd', 'd ddd', ' ddd ', ' d d '],
  ['   dd', 'd ddd', ' ddd ', '  dd '],
]
const DUCKING = [' ddddd', 'd d d ']
const BIRD = [['b b', ' b '], [' b ', 'b b']]
const cactus = (w: number, h: number) => Array.from({ length: h }, (_, r) => (w === 2 ? 'cc' : r === 1 ? 'ccc' : ' c '))

const fresh = (surface: ClientSurface<State>) => {
  const { w, h } = sizeFor(surface.columns, surface.rows)
  return newDino(w, h)
}

export default function DinoBoard(props: Props, surface: ClientSurface<State>) {
  const { Box, Text } = surface.elements

  if (surface.state === undefined) {
    surface.setState({ ...base(props), playing: true, g: fresh(surface), seenPulseSeq: props?.pulse?.seq ?? 0 })
    surface.every(100, () => {
      const s = surface.state
      if (!s || !s.playing || s.banner || s.g.over) return
      const g = tick(s.g)
      if (g.over) surface.post({ game: 'dino', score: Math.floor(g.distance) })
      surface.setState({ ...s, g })
    })
    // click the board to give it the keyboard: space/up jumps, down ducks, p pauses, r restarts
    surface.onKey(({ key }) => {
      const s = surface.state
      if (!s) return
      const k = key === 'space' ? ' ' : key.toLowerCase()
      if (k === 'p') {
        if (!s.g.over) surface.setState({ ...s, banner: false, playing: !s.playing })
        return
      }
      if (k === 'r') {
        surface.setState({ ...s, banner: false, playing: true, g: fresh(surface) })
        return
      }
      const act = k === ' ' || k === 'up' || k === 'w' ? jump : k === 'down' || k === 's' ? duck : undefined
      if (act) surface.setState({ ...s, banner: false, playing: true, g: act(s.g) })
    })
  }
  claudeDone(props, surface)

  const s = surface.state
  if (!s) return <Text dimColor>dino · waiting for the plugin to load it</Text>

  // a real event landed since the last render: apply it once, same idiom claudeDone uses for props.done
  const seq = props?.pulse?.seq
  if (seq !== undefined && seq !== s.seenPulseSeq) {
    surface.setState({ ...s, seenPulseSeq: seq, g: pulse(s.g, props!.pulse!.type) })
  }

  const g = s.g
  const ground = g.h - 1
  const c = canvas(g.w, g.h)
  // the ground, with pebbles that scroll left as you run
  for (let x = 0; x < g.w; x++) c.set(x, ground, (x + Math.floor(g.distance)) % 7 === 0 ? 'white' : 'gray')
  for (const o of g.obstacles) {
    const rows = o.kind === 'bird' ? BIRD[g.ticks % 4 < 2 ? 0 : 1] : cactus(o.w, o.h)
    c.sprite(rows, o.x, ground - o.alt - o.h, { c: 'green', b: 'magenta' })
  }
  const dino = box(g) === DUCKED ? DUCKING : RUN[g.alt > 0 ? 0 : Math.floor(g.ticks / 2) % 2]
  c.sprite(dino, DINO_X, ground - g.alt - dino.length, { d: g.over ? 'red' : g.shield > 0 ? 'yellow' : 'white' })

  const score = Math.floor(g.distance)
  const text = g.over ? `dino · crashed at ${score} · r restarts`
    : !s.playing ? `dino · paused · ${score} · p resumes`
    : `dino · space/↑ jump · ↓ duck · speed ${g.speed.toFixed(1)}${g.shield > 0 ? ' · shielded' : ''} · ${score}`

  return (
    <Box flexDirection="column">
