/* @jsx h */
import type { ClientSurface } from 'claude-code'
import { base, canvas, claudeDone, statusLine, type Base } from './common.tsx'
import { fire, move, newShooter, pulse, SHIP_X, tick, type Shooter } from '../games/shooter.ts'
import type { BuildEvent } from '../games/signals.ts'

// The shooter's board. A game's state lives entirely here; only the final score is posted up. It sizes
// itself from the height it's given and draws in half-block pixels on the shared canvas.

type Props = { pulse: { type: BuildEvent; seq: number } | null; best?: number; done?: number } | undefined
type State = Base & { g: Shooter; seenPulseSeq: number }

const sizeFor = (columns: number, rows: number) => ({
  w: Math.max(30, Math.min(72, columns - 4)),
  h: Math.max(8, (rows - 3) * 2),
})

// sprites, top row first: s = hull, w = cockpit; each enemy kind has its own shape and color
const SHIP_ROWS = ['ss   ', ' sssw', 'ss   ']
const ENEMY_ROWS = [
  ['eee', 'e e'],
  [' ee ', 'eeee', 'e  e'],
  ['e e', ' e ', 'e e'],
]
const SPINNING = [' e ', 'eee', ' e ']
// a sparse starfield drifting left at half the enemies' pace
const star = (x: number, y: number) => ((Math.imul(x, 73856093) ^ Math.imul(y, 19349663)) >>> 0) % 53 === 0

const fresh = (surface: ClientSurface<State>) => {
  const { w, h } = sizeFor(surface.columns, surface.rows)
  return newShooter(w, h)
}

export default function ShooterBoard(props: Props, surface: ClientSurface<State>) {
  const { Box, Text } = surface.elements

  if (surface.state === undefined) {
    surface.setState({ ...base(props), playing: true, g: fresh(surface), seenPulseSeq: props?.pulse?.seq ?? 0 })
    surface.every(100, () => {
      const s = surface.state
      if (!s || !s.playing || s.banner || s.g.over) return
      const g = tick(s.g)
      if (g.over) surface.post({ game: 'shooter', score: g.score })
      surface.setState({ ...s, g })
    })
    // click the board to give it the keyboard: up/down move, space/f fires, p pauses, r restarts
    surface.onKey(({ key }) => {
      const s = surface.state
      if (!s) return
      const k = key === 'space' ? ' ' : key.toLowerCase()
      if (k === 'p') {
        if (!s.g.over) surface.setState({ ...s, banner: false, playing: !s.playing })
        return
      }
      if (k === 'r') {
        surface.setState({ ...s, banner: false, playing: true, g: fresh(surface) })
        return
      }
      const next = k === ' ' || k === 'f' ? fire(s.g)
        : k === 'up' || k === 'w' ? move(s.g, -1)
        : k === 'down' || k === 's' ? move(s.g, 1)
        : undefined
      if (next) surface.setState({ ...s, banner: false, playing: true, g: next })
    })
  }
  claudeDone(props, surface)

  const s = surface.state
  if (!s) return <Text dimColor>shooter · waiting for the plugin to load it</Text>

  // a real event landed since the last render: apply it once, same idiom claudeDone uses for props.done
  const seq = props?.pulse?.seq
  if (seq !== undefined && seq !== s.seenPulseSeq) {
    surface.setState({ ...s, seenPulseSeq: seq, g: pulse(s.g, props!.pulse!.type) })
  }

  const g = s.g
  const c = canvas(g.w, g.h)
  const drift = Math.floor(g.ticks / 2)
  for (let y = 0; y < g.h; y++) for (let x = 0; x < g.w; x++) if (star(x + drift, y)) c.set(x, y, 'gray')
  for (const e of g.enemies) {
    const rows = e.kind === 2 && g.ticks % 4 < 2 ? SPINNING : ENEMY_ROWS[e.kind]
    const color = e.kind === 0 ? 'red' : e.kind === 1 ? (e.hp > 1 ? 'magenta' : 'magentaBright') : 'green'
    c.sprite(rows, e.x, e.y, { e: color })
  }
  for (const shot of g.shots) {
    if (shot.dx > 0) {
      c.set(shot.x - 1, shot.y, 'yellow')
      c.set(shot.x, shot.y, 'yellowBright')
    } else c.set(shot.x, shot.y, 'redBright')
  }
  // the ship blinks while invulnerable; its engine flame flickers
  if (!(g.invuln > 0 && g.ticks % 2 === 1)) {
    c.sprite(SHIP_ROWS, SHIP_X, g.shipY, { s: g.over ? 'red' : 'cyan', w: 'white' })
    if (!g.over) c.set(SHIP_X - 1, g.shipY + 1, g.ticks % 2 === 0 ? 'yellow' : 'red')
  }

  const hud = `level ${g.level} · ${'♥'.repeat(Math.max(0, g.lives))} · ${g.score}${g.power > 0 ? ' · triple shot' : ''}`
  const text = g.over ? `shooter · game over at ${g.score} · r restarts`
    : !s.playing ? `shooter · paused · ${hud} · p resumes`
    : `shooter · ↑ ↓ move · space fires · ${hud}`

  return (
    <Box flexDirection="column">
      <Box flexDirection="column" borderStyle="round" borderColor={g.over ? 'red' : 'gray'} width={g.w + 2}>{c.draw(Text)}</Box>
      {statusLine(Text, !!s.banner, `${text} · best ${props?.best ?? 0}`)}
    </Box>
  )
}

