// Terminal Racer: pure game logic. Your car sits fixed near the left edge of a horizontal track,
// facing right; oncoming cars enter from the right edge and scroll left toward you across one of three
// lanes. Speed climbs continuously and drives how often a new car spawns, so the road gets busier over a
// run. ../boards/racer.tsx runs it on its own frame clock and draws it.

// look: a random number in [0, 1) rolled at spawn, so the board can give each oncoming car its own
// shape and color and keep it for the whole trip; the rules never read it
export type Obstacle = { lane: number; x: number; look?: number }
export type Racer = {
  lanes: number; trackLen: number; carX: number; car: number
  obstacles: Obstacle[]; speed: number; ticks: number; distance: number; shield: number
  over: boolean
}

// every car, yours and theirs, is CAR_W track cells wide; collision is a box overlap on that width so
// what you see touching is exactly what crashes
export const CAR_W = 2
const LANES = 3
const CAR_X = 2
const MAX_SPEED = 4
// room between two cars in the same lane, so their sprites never overlap
const MIN_GAP = CAR_W + 1
// two cars in different lanes block your column at the same time when their x is within 2*CAR_W-1;
// never letting all lanes have a car inside this window guarantees a free lane at every tick (with a
// little slack on top, so it's humanly dodgeable, not just theoretically)
const WALL = 2 * CAR_W + 4

export function newRacer(trackLen = 30): Racer {
  return { lanes: LANES, trackLen, carX: CAR_X, car: Math.floor(LANES / 2), obstacles: [], speed: 1, ticks: 0, distance: 0, shield: 0, over: false }
}

export const steer = (g: Racer, dir: -1 | 1): Racer =>
  g.over ? g : { ...g, car: Math.max(0, Math.min(g.lanes - 1, g.car + dir)) }

const spawnChance = (speed: number) => Math.min(0.45, 0.12 + speed * 0.08)

// a new car may enter `lane` at the right edge only if that lane has room and it wouldn't complete a
// wall across every lane. Cars never change speed relative to each other, so a rule checked at spawn
// holds for their whole trip.
export function canSpawn(obstacles: Obstacle[], lane: number, g: Pick<Racer, 'lanes' | 'trackLen'>): boolean {
  const edge = g.trackLen - 1
  if (obstacles.some(o => o.lane === lane && o.x > edge - MIN_GAP)) return false
  const blocked = new Set(obstacles.filter(o => o.lane !== lane && o.x > edge - WALL).map(o => o.lane))
  return blocked.size < g.lanes - 1
}

const hits = (g: Racer, o: Obstacle) => o.lane === g.car && Math.abs(o.x - g.carX) < CAR_W

// one grid step: scroll every car one cell left, maybe spawn one at the right edge, check for an overlap
// with yours, and let a shield decay whether or not it was used
export function tick(g: Racer, rand = Math.random): Racer {
  if (g.over) return g
  const speed = Math.min(MAX_SPEED, g.speed + 0.01)
  let obstacles = g.obstacles.map(o => ({ ...o, x: o.x - 1 })).filter(o => o.x > -CAR_W)
  if (rand() < spawnChance(speed)) {
    const lane = Math.floor(rand() * g.lanes)
    if (canSpawn(obstacles, lane, g)) obstacles = [...obstacles, { lane, x: g.trackLen - 1, look: rand() }]
  }
  const hit = obstacles.some(o => hits(g, o))
  const shielded = hit && g.shield > 0
  return {
    ...g,
    obstacles: shielded ? obstacles.filter(o => !hits(g, o)) : obstacles,
    speed, ticks: g.ticks + 1, distance: g.distance + 1,
    shield: Math.max(0, g.shield - 1),
    over: hit && !shielded,
  }
}

export type Pulse = 'edit' | 'test-pass' | 'test-fail' | 'commit'

// one real build event, landed on the run in progress
export function pulse(g: Racer, event: Pulse): Racer {
  if (g.over) return g
  if (event === 'edit') return { ...g, distance: g.distance + 1 }
  if (event === 'test-pass') {
    // clears the nearest oncoming car in your lane
    const nearest = g.obstacles.filter(o => o.lane === g.car).sort((a, b) => a.x - b.x)[0]
    const obstacles = nearest ? g.obstacles.filter(o => o !== nearest) : g.obstacles
    return { ...g, obstacles, distance: g.distance + 5 }
  }
  if (event === 'test-fail') {
    // a hazard in your lane — unless that would crowd it or wall off the road
    if (!canSpawn(g.obstacles, g.car, g)) return g
    return { ...g, obstacles: [...g.obstacles, { lane: g.car, x: g.trackLen - 1, look: 0 }] }
  }
  return { ...g, shield: g.shield + 20, distance: g.distance + 15 } // commit
}

