// Breakout: pure game logic. Everything is in pixels — the board draws each pixel as half of a
// character cell, so a pixel is one character wide and half a row tall. The paddle sits on the bottom
// pixel row, bricks fill rows from the top, and a level is cleared when the last brick breaks.
// ../boards/breakout.tsx runs it on its own frame clock and draws it.

import type { BuildEvent } from './signals.ts'

export type Ball = { x: number; y: number; dx: number; dy: number }
export type Brick = { x: number; y: number; hp: number }
export type Breakout = {
  w: number; h: number
  paddle: number; paddleW: number
  ball: Ball; launched: boolean
  bricks: Brick[]; level: number; score: number; lives: number
  over: boolean
}

export const BRICK_W = 4
const TOP = 1 // one empty pixel row above the bricks
const STEP = 3 // paddle pixels per key press
const MAX_LIVES = 5

// the ball speeds up every level, capped so it stays catchable at ten frames a second
const speedFor = (level: number) => Math.min(1.6, 0.8 + 0.15 * level)

// full-width rows of bricks, one more row each level (leaving the lower two thirds for play); from
// level 3 the top row is armored and takes two hits
export function bricksFor(w: number, h: number, level: number): Brick[] {
  const rows = Math.max(1, Math.min(2 + level, Math.floor(h / 3)))
  const cols = Math.floor(w / BRICK_W)
  const left = Math.floor((w - cols * BRICK_W) / 2)
  const bricks: Brick[] = []
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) bricks.push({ x: left + c * BRICK_W, y: TOP + r, hp: level >= 3 && r === 0 ? 2 : 1 })
  }
  return bricks
}

// the ball waits on top of the paddle until it's launched
const serve = (g: Breakout): Breakout => ({
  ...g,
  launched: false,
  ball: { x: g.paddle + g.paddleW / 2, y: g.h - 2, dx: 0, dy: 0 },
})

export function newBreakout(w: number, h: number): Breakout {
  const paddleW = Math.max(6, Math.floor(w / 6))
  return serve({
    w, h, paddle: Math.floor((w - paddleW) / 2), paddleW,
    ball: { x: 0, y: 0, dx: 0, dy: 0 }, launched: false,
    bricks: bricksFor(w, h, 1), level: 1, score: 0, lives: 3, over: false,
  })
}

export function movePaddle(g: Breakout, dir: -1 | 1): Breakout {
  if (g.over) return g
  const paddle = Math.max(0, Math.min(g.w - g.paddleW, g.paddle + dir * STEP))
  return g.launched ? { ...g, paddle } : { ...g, paddle, ball: { ...g.ball, x: paddle + g.paddleW / 2 } }
}

export function launch(g: Breakout): Breakout {
  if (g.over || g.launched) return g
  const s = speedFor(g.level)
  return { ...g, launched: true, ball: { ...g.ball, dx: s * 0.6, dy: -s * 0.8 } }
}

const brickAt = (bricks: Brick[], x: number, y: number) =>
  bricks.find(b => b.y === Math.floor(y) && x >= b.x && x < b.x + BRICK_W)

const damage = (bricks: Brick[], hit: Brick) =>
  hit.hp > 1 ? bricks.map(b => (b === hit ? { ...b, hp: b.hp - 1 } : b)) : bricks.filter(b => b !== hit)

// the last brick gone: next level, a fresh wall, and a faster serve
function settle(g: Breakout): Breakout {
  if (g.bricks.length > 0) return g
  const level = g.level + 1
  return serve({ ...g, level, bricks: bricksFor(g.w, g.h, level) })
}

// one frame. The ball moves in sub-steps of at most half a pixel, x then y, so it can never skip over a
// brick or the paddle, and each axis bounces on its own: hitting a brick's side flips dx, its top or
// bottom flips dy.
export function tick(g: Breakout): Breakout {
  if (g.over || !g.launched) return g
  let { x, y, dx, dy } = g.ball
  let bricks = g.bricks
  let score = g.score
  const hit = (b: Brick) => {
    bricks = damage(bricks, b)
    score += 10 * g.level
  }
  const paddleRow = g.h - 1
  const steps = Math.max(1, Math.ceil(Math.max(Math.abs(dx), Math.abs(dy)) / 0.5))
  for (let i = 0; i < steps && y < g.h; i++) {
    let nx = x + dx / steps
    if (nx < 0) { nx = -nx; dx = -dx }
    else if (nx >= g.w) { nx = Math.min(g.w - 0.001, 2 * g.w - nx); dx = -dx }
    const side = brickAt(bricks, nx, y)
    if (side) { hit(side); dx = -dx; nx = x }
    x = nx

    let ny = y + dy / steps
    if (ny < 0) { ny = -ny; dy = -dy }
    const face = brickAt(bricks, x, ny)
    if (face) { hit(face); dy = -dy; ny = y }
    // landing on the paddle sends it back up, angled by where it hit: the middle straight up, the
    // edges steeply sideways
    if (dy > 0 && y < paddleRow && ny >= paddleRow && x >= g.paddle && x < g.paddle + g.paddleW) {
      const speed = Math.hypot(dx, dy)
      const offset = (x - (g.paddle + g.paddleW / 2)) / (g.paddleW / 2)
      dx = speed * Math.max(-0.85, Math.min(0.85, offset))
      dy = -Math.sqrt(speed * speed - dx * dx)
      ny = paddleRow - 0.001
    }
    y = ny
  }
  if (y >= g.h) {
    const lives = g.lives - 1
    const missed = { ...g, bricks, score, lives }
    return lives > 0 ? serve(missed) : { ...missed, over: true, launched: false, ball: { x, y: paddleRow, dx: 0, dy: 0 } }
  }
  return settle({ ...g, bricks, score, ball: { x, y, dx, dy } })
}

export type Pulse = BuildEvent

const lowest = (bricks: Brick[]) => [...bricks].sort((a, b) => b.y - a.y || a.x - b.x)[0]

// one real build event: an edit scores a point, a passing test breaks the lowest brick for you, a
// failing test armors it (up to 3 hits), a commit is an extra life (up to 5)
export function pulse(g: Breakout, event: Pulse): Breakout {
  if (g.over) return g
  if (event === 'edit') return { ...g, score: g.score + 1 }
  if (event === 'commit') return { ...g, lives: Math.min(MAX_LIVES, g.lives + 1) }
  const target = lowest(g.bricks)
  if (!target) return g
  if (event === 'test-pass') return settle({ ...g, bricks: g.bricks.filter(b => b !== target), score: g.score + 10 * g.level })
  return { ...g, bricks: g.bricks.map(b => (b === target ? { ...b, hp: Math.min(3, b.hp + 1) } : b)) }
}

