// Dino Runner: pure game logic, in pixels. The dino runs in place near the left edge while cacti and
// birds scroll in from the right; it jumps over cacti and ducks under birds, and the run speeds up the
// whole time. Altitude is measured up from the ground. ../boards/dino.tsx runs it and draws it.

import type { BuildEvent } from './signals.ts'

export type Obstacle = { kind: 'cactus' | 'bird'; x: number; w: number; h: number; alt: number }
export type Dino = {
  w: number; h: number
  alt: number; vy: number; duck: number
  obstacles: Obstacle[]; speed: number; distance: number; shield: number; ticks: number
  over: boolean
}

export const DINO_X = 4
export const STAND = { w: 5, h: 4 }
export const DUCKED = { w: 6, h: 2 }
const JUMP_V = 2.0
const GRAVITY = 0.36 // a hop lasts about 12 ticks and peaks at 6.6 px, inside a 12-px field
const START_SPEED = 1.5
const MAX_SPEED = 3.5
// the next obstacle never spawns closer than a whole hop's travel plus room to land, so every gap is
// clearable: at the slowest speed a 5-px dino and a 3-px cactus overlap for at most 6 ticks, while a
// hop keeps it above 3 px for 9
const HOP_TICKS = 13
const BIRDS_FROM = 150
const BIRD_ALT = STAND.h - 1 // clips a standing dino's head, clears a ducking one
const DUCK_TICKS = 4

export function newDino(w: number, h: number): Dino {
  return { w, h, alt: 0, vy: 0, duck: 0, obstacles: [], speed: START_SPEED, distance: 0, shield: 0, ticks: 0, over: false }
}

const onGround = (g: Dino) => g.alt === 0 && g.vy === 0

export function jump(g: Dino): Dino {
  return g.over || !onGround(g) ? g : { ...g, vy: JUMP_V, duck: 0 }
}

// the terminal sends no key-up, so a duck lasts a few ticks and holding the key keeps renewing it; in
// the air, ducking dives straight back down
export function duck(g: Dino): Dino {
  if (g.over) return g
  return onGround(g) ? { ...g, duck: DUCK_TICKS } : { ...g, vy: Math.min(g.vy, -JUMP_V) }
}

export const box = (g: Dino) => (onGround(g) && g.duck > 0 ? DUCKED : STAND)

const hits = (g: Dino, o: Obstacle) => {
  const b = box(g)
  return o.x < DINO_X + b.w && o.x + o.w > DINO_X && o.alt < g.alt + b.h && o.alt + o.h > g.alt
}

const roomAtEdge = (obstacles: Obstacle[], w: number, speed: number) =>
  w - obstacles.reduce((right, o) => Math.max(right, o.x + o.w), -Infinity) >= speed * HOP_TICKS + 6

export function tick(g: Dino, rand = Math.random): Dino {
  if (g.over) return g
  const speed = Math.min(MAX_SPEED, g.speed + 0.003)
  let alt = g.alt + g.vy
  let vy = g.vy - GRAVITY
  if (alt <= 0) {
    alt = 0
    vy = 0
  }
  let obstacles = g.obstacles.map(o => ({ ...o, x: o.x - speed })).filter(o => o.x + o.w > 0)
  if (roomAtEdge(obstacles, g.w, speed) && rand() < 0.12) {
    const spawned: Obstacle = g.distance >= BIRDS_FROM && rand() < 0.35
      ? { kind: 'bird', x: g.w, w: 3, h: 2, alt: BIRD_ALT }
      : { kind: 'cactus', x: g.w, w: 2 + Math.floor(rand() * 2), h: 2 + Math.floor(rand() * 2), alt: 0 }
    obstacles = [...obstacles, spawned]
  }
  const next: Dino = {
    ...g, alt, vy, duck: Math.max(0, g.duck - 1), obstacles, speed,
    distance: g.distance + speed, shield: Math.max(0, g.shield - 1), ticks: g.ticks + 1,
  }
  const hit = next.obstacles.filter(o => hits(next, o))
  if (hit.length === 0) return next
  return g.shield > 0 ? { ...next, obstacles: next.obstacles.filter(o => !hit.includes(o)) } : { ...next, over: true }
}

export type Pulse = BuildEvent

// one real build event: an edit is a point, a passing test clears the next obstacle, a failing test drops
// a cactus at the edge (only where the gap rule allows), a commit shields you for 3 seconds
export function pulse(g: Dino, event: Pulse): Dino {
  if (g.over) return g
  if (event === 'edit') return { ...g, distance: g.distance + 1 }
  if (event === 'commit') return { ...g, shield: g.shield + 30 }
  if (event === 'test-pass') {
    const ahead = g.obstacles.filter(o => o.x + o.w > DINO_X).sort((a, b) => a.x - b.x)[0]
    return ahead ? { ...g, obstacles: g.obstacles.filter(o => o !== ahead), distance: g.distance + 10 } : g
  }
  if (!roomAtEdge(g.obstacles, g.w, g.speed)) return g
  return { ...g, obstacles: [...g.obstacles, { kind: 'cactus', x: g.w, w: 2, h: 2, alt: 0 }] }
}

