// Side-scrolling shooter: pure game logic, in pixels. Your ship sits near the left edge and moves up and
// down, firing right; enemies fly in from the right. Levels come from score and bring faster, denser
// waves. ../boards/shooter.tsx runs it and draws it.

import type { BuildEvent } from './signals.ts'

export type Enemy = { kind: 0 | 1 | 2; x: number; y: number; baseY: number; hp: number; vx: number }
export type Shot = { x: number; y: number; dx: number } // dx > 0 is yours, dx < 0 is an enemy bullet
export type Shooter = {
  w: number; h: number
  shipY: number; enemies: Enemy[]; shots: Shot[]
  cooldown: number; power: number; invuln: number
  score: number; lives: number; level: number; ticks: number
  over: boolean
}

export const SHIP_X = 1
export const SHIP = { w: 5, h: 3 }
// basic; armored (two hits, fires back from level 2); zigzag (weaves around its lane)
export const ENEMY = [
  { w: 3, h: 2, hp: 1, points: 10 },
  { w: 4, h: 3, hp: 2, points: 25 },
  { w: 3, h: 3, hp: 1, points: 15 },
] as const
const MOVE = 2
const COOLDOWN = 2
const SHOT_SPEED = 3
const BULLET_SPEED = 2
const INVULN = 15
const POWER = 50
const LEVEL_EVERY = 250
// the level keeps counting up, but waves stop getting faster and denser past this one: an enemy moving
// more than its own width per frame could slip past a shot or the ship
const MAX_PACE = 8

const clamp = (v: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, v))
const levelFor = (score: number) => 1 + Math.floor(score / LEVEL_EVERY)

export function newShooter(w: number, h: number): Shooter {
  return {
    w, h, shipY: Math.floor((h - SHIP.h) / 2), enemies: [], shots: [],
    cooldown: 0, power: 0, invuln: 0, score: 0, lives: 3, level: 1, ticks: 0, over: false,
  }
}

export const move = (g: Shooter, dir: -1 | 1): Shooter =>
  g.over ? g : { ...g, shipY: clamp(g.shipY + dir * MOVE, 0, g.h - SHIP.h) }

// one shot from the nose, or three while powered up; holding space auto-fires through key repeat
export function fire(g: Shooter): Shooter {
  if (g.over || g.cooldown > 0) return g
  const ys = g.power > 0 ? [g.shipY, g.shipY + 1, g.shipY + 2] : [g.shipY + 1]
  return { ...g, cooldown: COOLDOWN, shots: [...g.shots, ...ys.map(y => ({ x: SHIP_X + SHIP.w, y, dx: SHOT_SPEED }))] }
}

export function tick(g: Shooter, rand = Math.random): Shooter {
  if (g.over) return g
  const ticks = g.ticks + 1
  const level = levelFor(g.score)
  const pace = Math.min(level, MAX_PACE)
  let score = g.score

  let shots = g.shots.map(s => ({ ...s, x: s.x + s.dx }))
  let enemies = g.enemies
    .map(e => ({
      ...e,
      x: e.x - e.vx,
      y: e.kind === 2 ? clamp(e.baseY + Math.round(Math.sin(ticks / 3) * 2), 0, g.h - ENEMY[2].h) : e.y,
    }))
    .filter(e => e.x + ENEMY[e.kind].w > 0)

  if (level >= 2) {
    for (const e of enemies) if (e.kind === 1 && rand() < 0.03) shots.push({ x: e.x - 1, y: e.y + 1, dx: -BULLET_SPEED })
  }
  if (!enemies.some(e => e.x > g.w - 8) && rand() < Math.min(0.3, 0.08 + 0.03 * pace)) {
    const roll = rand()
    const kind: Enemy['kind'] = level >= 2 && roll < 0.3 ? 1 : roll < 0.65 ? 0 : 2
    const y = Math.floor(rand() * (g.h - ENEMY[kind].h + 1))
    enemies.push({ kind, x: g.w, y, baseY: y, hp: ENEMY[kind].hp, vx: 0.5 + 0.1 * pace + rand() * 0.3 })
  }

  // your shots hit along the whole path they moved this tick, so a fast shot can't skip past an enemy
  const flying: Shot[] = []
  for (const s of shots) {
    const target = s.dx > 0 && enemies.find(e =>
      e.hp > 0 && s.y >= e.y && s.y < e.y + ENEMY[e.kind].h && e.x <= s.x && e.x + ENEMY[e.kind].w > s.x - s.dx)
    if (!target) {
      flying.push(s)
      continue
    }
    target.hp -= 1
    if (target.hp === 0) score += ENEMY[target.kind].points * pace
  }
  enemies = enemies.filter(e => e.hp > 0)
  shots = flying.filter(s => (s.dx > 0 ? s.x < g.w : s.x + BULLET_SPEED >= 0))

  // anything touching the ship costs a life, then a moment of invulnerability
  const onShip = (x0: number, x1: number, y0: number, y1: number) =>
    x0 < SHIP_X + SHIP.w && x1 > SHIP_X && y0 < g.shipY + SHIP.h && y1 > g.shipY
  const rammed = enemies.filter(e => onShip(e.x, e.x + ENEMY[e.kind].w, e.y, e.y + ENEMY[e.kind].h))
  const shotDown = shots.filter(s => s.dx < 0 && onShip(s.x, s.x + BULLET_SPEED, s.y, s.y + 1))
  let lives = g.lives
  let invuln = Math.max(0, g.invuln - 1)
  if (rammed.length > 0 || shotDown.length > 0) {
    enemies = enemies.filter(e => !rammed.includes(e))
    shots = shots.filter(s => !shotDown.includes(s))
    if (invuln === 0) {
      lives -= 1
      invuln = INVULN
    }
  }

  return {
    ...g, enemies, shots, score, lives, invuln, ticks, level: levelFor(score),
    cooldown: Math.max(0, g.cooldown - 1), power: Math.max(0, g.power - 1), over: lives <= 0,
  }
}

export type Pulse = BuildEvent

// one real build event: an edit is a point, a passing test powers up a triple shot, a failing test sends
// an extra pair of enemies, a commit is a bomb that destroys (and scores) everything on screen
export function pulse(g: Shooter, event: Pulse): Shooter {
  if (g.over) return g
  if (event === 'edit') return { ...g, score: g.score + 1 }
  if (event === 'test-pass') return { ...g, power: g.power + POWER }
  if (event === 'test-fail') {
    const pair = [0, g.h - ENEMY[0].h].map((y): Enemy => ({ kind: 0, x: g.w, y, baseY: y, hp: ENEMY[0].hp, vx: 0.5 + 0.1 * Math.min(g.level, MAX_PACE) }))
    return { ...g, enemies: [...g.enemies, ...pair] }
  }
  const score = g.score + g.enemies.reduce((sum, e) => sum + ENEMY[e.kind].points * Math.min(g.level, MAX_PACE), 0)
  return { ...g, score, level: levelFor(score), enemies: [], shots: g.shots.filter(s => s.dx > 0) }
}

